package com.crypto.laplace.stop;
import com.crypto.binance.client.BinanceFuturesClient; import com.crypto.common.enums.PositionSide; import com.crypto.domain.model.Kline; import com.crypto.laplace.execution.*; import com.crypto.laplace.model.LaplacePositionStatus; import com.crypto.laplace.persistence.*; import com.crypto.laplace.pool.LaplaceCoinPoolService; import java.math.*; import java.time.*; import java.util.*; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Slf4j @Service @RequiredArgsConstructor public class LaplaceFiveMinuteStopService { private final BinanceFuturesClient client; private final LaplacePaperPositionRepository positions; private final LaplacePaperExecutionService execution; private final LaplacePaperTradeCoordinator coordinator;
 public void checkOpenPositions(){Instant start=Instant.now();List<LaplacePaperPositionEntity> open=positions.findByStrategyAndStatus(LaplacePaperExecutionService.STRATEGY,LaplacePositionStatus.OPEN);int candles=0, stopped=0;Set<String> errors=new HashSet<>();for(var p:open)try{candles+=check(p)?1:0;if(p.getStatus()==LaplacePositionStatus.CLOSED_BY_STOP_LOSS)stopped++;}catch(RuntimeException e){errors.add(p.getSymbol());log.error("LAPLACE_STOP_CANDLE_LOAD_FAILED symbol={} positionId={}",p.getSymbol(),p.getId(),e);}log.info("LAPLACE_5M_STOP_CHECK openPositions={} symbols={} candles={} stopped={} apiErrors={} startedAt={} finishedAt={}",open.size(),open.stream().map(LaplacePaperPositionEntity::getSymbol).distinct().count(),candles,stopped,errors,start,Instant.now());}
 public void checkLiveBookPrices(){Map<String,com.crypto.domain.model.BookTicker> books=new HashMap<>();for(var b:client.getAllBookTickers())if(b!=null&&b.getSymbol()!=null)books.put(b.getSymbol(),b);Instant now=Instant.now();for(var p:positions.findByStrategyAndStatus(LaplacePaperExecutionService.STRATEGY,LaplacePositionStatus.OPEN)){var b=books.get(p.getSymbol());if(b==null||b.getBidPrice()==null||b.getAskPrice()==null)continue;p.setLastObservedBid(b.getBidPrice());p.setLastObservedAsk(b.getAskPrice());p.setLastStopPriceCheckedAt(now);p.setMinBidSinceEntry(p.getMinBidSinceEntry()==null?b.getBidPrice():p.getMinBidSinceEntry().min(b.getBidPrice()));p.setMaxAskSinceEntry(p.getMaxAskSinceEntry()==null?b.getAskPrice():p.getMaxAskSinceEntry().max(b.getAskPrice()));positions.save(p);boolean hit=p.getSide()==PositionSide.LONG?b.getBidPrice().compareTo(p.getStopPrice())<=0:b.getAskPrice().compareTo(p.getStopPrice())>=0;if(hit){BigDecimal trigger=p.getSide()==PositionSide.LONG?b.getBidPrice():b.getAskPrice();Kline observed=Kline.builder().openTime(now).closeTime(now).high(trigger).low(trigger).close(trigger).closed(true).build();closeStop(p.getId(),observed);}}}
 public void catchUpOpenPositions(){Instant now=Instant.now();for(var p:positions.findByStrategyAndStatus(LaplacePaperExecutionService.STRATEGY,LaplacePositionStatus.OPEN)){Instant entryFloor=p.getEntryTime().truncatedTo(java.time.temporal.ChronoUnit.HOURS).plusSeconds((p.getEntryTime().getEpochSecond()%3600/300+1)*300);Instant cursor=p.getLastChecked5mCandleCloseTime()==null?entryFloor:p.getLastChecked5mCandleCloseTime().plusMillis(1);while(cursor.isBefore(now)){List<Kline> batch=client.getKlines(p.getSymbol(),"5m",40,cursor).stream().filter(c->c.getCloseTime()!=null&&!c.getCloseTime().isAfter(now)&&c.getOpenTime()!=null&&!c.getOpenTime().isBefore(entryFloor)).sorted(Comparator.comparing(Kline::getOpenTime)).toList();if(batch.isEmpty())break;boolean stopped=false;for(Kline c:batch){boolean hit=p.getSide()==PositionSide.LONG?c.getLow().compareTo(p.getStopPrice())<=0:c.getHigh().compareTo(p.getStopPrice())>=0;if(hit){closeStop(p.getId(),c);stopped=true;break;}p.setLastChecked5mCandleCloseTime(c.getCloseTime());positions.save(p);}if(stopped||batch.size()<40)break;cursor=batch.getLast().getCloseTime().plusMillis(1);}}}
 private boolean check(LaplacePaperPositionEntity p){if(p.getStopPrice()==null&&p.getEntryExecutionPrice()!=null){p.setStopLossPct(new BigDecimal("0.055"));p.setStopPrice(p.getSide()==PositionSide.LONG?p.getEntryExecutionPrice().multiply(new BigDecimal("0.945")):p.getEntryExecutionPrice().multiply(new BigDecimal("1.055")));positions.save(p);}List<Kline> all=client.getKlines(p.getSymbol(),"5m",40);Instant now=Instant.now();Instant entryFloor=p.getEntryTime().truncatedTo(java.time.temporal.ChronoUnit.HOURS).plusSeconds((p.getEntryTime().getEpochSecond()%3600/300+1)*300);Instant after=p.getLastChecked5mCandleCloseTime()==null?entryFloor:p.getLastChecked5mCandleCloseTime();List<Kline> closed=all.stream().filter(c->c!=null&&c.getCloseTime()!=null&&!c.getCloseTime().isAfter(now)&&!Boolean.FALSE.equals(c.getClosed())&&c.getCloseTime().isAfter(after)).sorted(Comparator.comparing(Kline::getCloseTime)).toList();for(Kline c:closed){boolean hit=p.getSide()==PositionSide.LONG?c.getLow().compareTo(p.getStopPrice())<=0:c.getHigh().compareTo(p.getStopPrice())>=0;if(hit){closeStop(p.getId(),c);return true;} p.setLastChecked5mCandleCloseTime(c.getCloseTime());positions.save(p);}return false;}
 public void closeStop(String id,Kline c){execution.closeByStop(id,c).ifPresent(p->{coordinator.onStopLossClosed(p.getSymbol(),p.getEntryRawSignal(),p.getSide().name(),p.getId(),p.getExitTime());execution.drainOutbox();log.info("LAPLACE_STOP_TRIGGERED positionId={} symbol={} side={} entryPrice={} stopPrice={} candleOpenTime={} candleCloseTime={} candleHigh={} candleLow={} candleClose={} exitPrice={} grossPnl={} entryFee={} exitFee={} netPnl={}",p.getId(),p.getSymbol(),p.getSide(),p.getEntryExecutionPrice(),p.getStopPrice(),c.getOpenTime(),c.getCloseTime(),c.getHigh(),c.getLow(),c.getClose(),p.getExitExecutionPrice(),p.getGrossPnl(),p.getEntryFee(),p.getExitFee(),p.getNetPnl());}); }
}
